function t(){let o=document.querySelectorAll(".local-time");o.length&&o.forEach(e=>{let n=e.id||"Europe/Prague",r=new Date,m={timeZone:n,timeZoneName:"short",hour:"2-digit",hour12:!0,minute:"2-digit"},i=new Intl.DateTimeFormat([],m).format(r);e.textContent="",e.textContent=i})}t();setInterval(t,6e4);t();
